        # [doc = " This trait defines the callbacks you can expect to receive when"] # [doc = " employing the ExprUseVisitor."] pub trait Delegate < 'tcx > { # [doc = " The value found at `place` is moved, depending"] # [doc = " on `mode`. Where `diag_expr_id` is the id used for diagnostics for `place`."] # [doc = ""] # [doc = " If the value is `Copy`, [`copy`][Self::copy] is called instead, which"] # [doc = " by default falls back to [`borrow`][Self::borrow]."] # [doc = ""] # [doc = " The parameter `diag_expr_id` indicates the HIR id that ought to be used for"] # [doc = " diagnostics. Around pattern matching such as `let pat = expr`, the diagnostic"] # [doc = " id will be the id of the expression `expr` but the place itself will have"] # [doc = " the id of the binding in the pattern `pat`."] fn consume (& mut self , place_with_id : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId) ; # [doc = " The value found at `place` is used, depending"] # [doc = " on `mode`. Where `diag_expr_id` is the id used for diagnostics for `place`."] # [doc = ""] # [doc = " Use of a `Copy` type in a ByUse context is considered a use"] # [doc = " by `ImmBorrow` and `borrow` is called instead. This is because"] # [doc = " a shared borrow is the \"minimum access\" that would be needed"] # [doc = " to perform a copy."] # [doc = ""] # [doc = ""] # [doc = " The parameter `diag_expr_id` indicates the HIR id that ought to be used for"] # [doc = " diagnostics. Around pattern matching such as `let pat = expr`, the diagnostic"] # [doc = " id will be the id of the expression `expr` but the place itself will have"] # [doc = " the id of the binding in the pattern `pat`."] fn use_cloned (& mut self , place_with_id : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId) ; # [doc = " The value found at `place` is being borrowed with kind `bk`."] # [doc = " `diag_expr_id` is the id used for diagnostics (see `consume` for more details)."] fn borrow (& mut self , place_with_id : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId , bk : ty :: BorrowKind ,) ; # [doc = " The value found at `place` is being copied."] # [doc = " `diag_expr_id` is the id used for diagnostics (see `consume` for more details)."] # [doc = ""] # [doc = " If an implementation is not provided, use of a `Copy` type in a ByValue context is instead"] # [doc = " considered a use by `ImmBorrow` and `borrow` is called instead. This is because a shared"] # [doc = " borrow is the \"minimum access\" that would be needed to perform a copy."] fn copy (& mut self , place_with_id : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId) { self . borrow (place_with_id , diag_expr_id , ty :: BorrowKind :: Immutable) } # [doc = " The path at `assignee_place` is being assigned to."] # [doc = " `diag_expr_id` is the id used for diagnostics (see `consume` for more details)."] fn mutate (& mut self , assignee_place : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId) ; # [doc = " The path at `binding_place` is a binding that is being initialized."] # [doc = ""] # [doc = " This covers cases such as `let x = 42;`"] fn bind (& mut self , binding_place : & PlaceWithHirId < 'tcx > , diag_expr_id : HirId) { self . mutate (binding_place , diag_expr_id) } # [doc = " The `place` should be a fake read because of specified `cause`."] fn fake_read (& mut self , place_with_id : & PlaceWithHirId < 'tcx > , cause : FakeReadCause , diag_expr_id : HirId ,) ; }
